@Test
	public void testIndexedProperties_1_oe() throws Exception {
		LazyDynaBean lazyDynaBean = new LazyDynaBean();
		BeanUtilsBean beanUtilsBean = BeanUtilsBean.getInstance();
		beanUtilsBean.setProperty(lazyDynaBean, "x[0]", "x1");
		beanUtilsBean.setProperty(lazyDynaBean, "x[1]", "x2");
		Object x = lazyDynaBean.get("x");
		assertEquals("[x1, x2]", x.toString());
	}

public void testIssue_BEANUTILS_381_getMatchingAccessibleMethod_1_oe() {

        final Class<?> target = TestServiceBean.class;
        final String methodName = "performOp";
